import{_ as i,o as a,c as r,a2 as l}from"./chunks/framework.CTZjucLO.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-politie.md","filePath":"regulament-politie.md"}'),t={name:"regulament-politie.md"};function o(n,e,u,c,s,h){return a(),r("div",null,[...e[0]||(e[0]=[l('<h2 id="📜-regulament-general-politie-romana" tabindex="-1">📜 Regulament General Poliție (Română) <a class="header-anchor" href="#📜-regulament-general-politie-romana" aria-label="Permalink to &quot;📜 Regulament General Poliție (Română)&quot;">​</a></h2><hr><h2 id="cap-1-dispozitii-generale" tabindex="-1">CAP. 1 - DISPOZIȚII GENERALE <a class="header-anchor" href="#cap-1-dispozitii-generale" aria-label="Permalink to &quot;CAP. 1 - DISPOZIȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-respectarea-regulamentelor" tabindex="-1">1.1 Respectarea regulamentelor <a class="header-anchor" href="#_1-1-respectarea-regulamentelor" aria-label="Permalink to &quot;1.1 Respectarea regulamentelor&quot;">​</a></h3><p>Toți membrii Poliției <strong>Legacy Of CLT</strong> au obligația de a respecta toate regulamentele și directivele interne.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este obligatorie respectarea regulamentului Poliției.</li><li>Este obligatorie respectarea regulamentului general al serverului.</li><li>Este obligatorie respectarea Codului Penal.</li><li>Este obligatorie respectarea Codului de Procedură Penală.</li><li>Este obligatorie respectarea regulamentului MDT.</li><li>Toate directivele emise de conducerea departamentului trebuie respectate.</li></ul><hr><h3 id="_1-2-comportamentul-politistului" tabindex="-1">1.2 Comportamentul polițistului <a class="header-anchor" href="#_1-2-comportamentul-politistului" aria-label="Permalink to &quot;1.2 Comportamentul polițistului&quot;">​</a></h3><p>Fiecare polițist trebuie să adopte permanent o conduită profesională.</p><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Respectă colegii, cetățenii și membrii Staff.</li><li>Utilizează un limbaj civilizat în orice situație.</li><li>Sunt interzise jignirile și amenințările.</li><li>Ridicarea nejustificată a tonului este interzisă.</li><li>Orice comportament care afectează imaginea departamentului poate fi sancționat.</li></ul><hr><h3 id="_1-3-utilizarea-fortei" tabindex="-1">1.3 Utilizarea forței <a class="header-anchor" href="#_1-3-utilizarea-fortei" aria-label="Permalink to &quot;1.3 Utilizarea forței&quot;">​</a></h3><p>Forța poate fi utilizată doar în situațiile justificate prin Roleplay.</p><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Conflictele trebuie soluționate prin mijloace Roleplay.</li><li>Este interzisă utilizarea forței fără motiv întemeiat.</li><li>Sunt interzise acțiunile nerealiste sau disproporționate.</li></ul><hr><h3 id="_1-4-vehicule-personale" tabindex="-1">1.4 Vehicule personale <a class="header-anchor" href="#_1-4-vehicule-personale" aria-label="Permalink to &quot;1.4 Vehicule personale&quot;">​</a></h3><p>Vehiculele personale nu pot fi utilizate în timpul serviciului.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă utilizarea vehiculelor personale în timpul serviciului.</li><li>Este interzisă utilizarea vehiculelor cetățenilor.</li><li>Excepțiile sunt permise doar în situații critice sau operațiuni speciale aprobate.</li></ul><hr><h3 id="_1-5-echipamente-si-bunuri-ale-politiei" tabindex="-1">1.5 Echipamente și bunuri ale Poliției <a class="header-anchor" href="#_1-5-echipamente-si-bunuri-ale-politiei" aria-label="Permalink to &quot;1.5 Echipamente și bunuri ale Poliției&quot;">​</a></h3><p>Toate echipamentele departamentului sunt destinate exclusiv activităților de serviciu.</p><h3 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Vehiculele Poliției pot fi folosite doar în interes de serviciu.</li><li>Echipamentele și funcțiile departamentului nu pot fi utilizate în scop personal.</li></ul><hr><h3 id="_1-6-vehicule-speciale" tabindex="-1">1.6 Vehicule speciale <a class="header-anchor" href="#_1-6-vehicule-speciale" aria-label="Permalink to &quot;1.6 Vehicule speciale&quot;">​</a></h3><p>Vehiculele speciale pot fi utilizate doar de personalul autorizat.</p><h3 id="reguli-5" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-5" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Vehiculele High-Speed pot fi conduse doar de personal certificat.</li><li>Vehiculele Off-Road pot fi utilizate doar de personal autorizat.</li><li>Unitățile Aeriene sunt rezervate exclusiv personalului certificat.</li><li>Orice alt vehicul special necesită certificarea corespunzătoare.</li></ul><hr><h3 id="_1-7-aspectul-politistului" tabindex="-1">1.7 Aspectul polițistului <a class="header-anchor" href="#_1-7-aspectul-politistului" aria-label="Permalink to &quot;1.7 Aspectul polițistului&quot;">​</a></h3><p>Aspectul unui polițist trebuie să reflecte imaginea instituției.</p><h3 id="reguli-6" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-6" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Uniforma trebuie purtată corespunzător.</li><li>Sunt interzise elementele vestimentare neprofesionale.</li><li>Sunt interzise tatuajele faciale excesive.</li><li>Sunt interzise stilurile extreme incompatibile cu imaginea Poliției.</li></ul><hr><h2 id="cap-2-activitatea-in-departament" tabindex="-1">CAP. 2 - ACTIVITATEA ÎN DEPARTAMENT <a class="header-anchor" href="#cap-2-activitatea-in-departament" aria-label="Permalink to &quot;CAP. 2 - ACTIVITATEA ÎN DEPARTAMENT&quot;">​</a></h2><h3 id="_2-1-activitatea-membrilor" tabindex="-1">2.1 Activitatea membrilor <a class="header-anchor" href="#_2-1-activitatea-membrilor" aria-label="Permalink to &quot;2.1 Activitatea membrilor&quot;">​</a></h3><p>Participarea activă la viața departamentului este obligatorie.</p><h3 id="reguli-7" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-7" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Membrii trebuie să fie activi.</li><li>Inactivitatea fără aprobare poate conduce la demitere.</li></ul><hr><h3 id="_2-2-raportul-de-activitate" tabindex="-1">2.2 Raportul de activitate <a class="header-anchor" href="#_2-2-raportul-de-activitate" aria-label="Permalink to &quot;2.2 Raportul de activitate&quot;">​</a></h3><p>Fiecare polițist trebuie să îndeplinească raportul minim stabilit.</p><h3 id="reguli-8" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-8" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Raportul trebuie realizat în perioada stabilită.</li><li>Raportul este verificat de conducerea departamentului.</li></ul><hr><h3 id="_2-3-responsabilitati" tabindex="-1">2.3 Responsabilități <a class="header-anchor" href="#_2-3-responsabilitati" aria-label="Permalink to &quot;2.3 Responsabilități&quot;">​</a></h3><p>Evitarea responsabilităților reprezintă abatere disciplinară.</p><h3 id="reguli-9" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-9" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Fiecare membru trebuie să își îndeplinească atribuțiile.</li><li>Refuzul nejustificat al activităților poate fi sancționat.</li></ul><hr><h3 id="_2-4-raport-si-pontaj" tabindex="-1">2.4 Raport și pontaj <a class="header-anchor" href="#_2-4-raport-si-pontaj" aria-label="Permalink to &quot;2.4 Raport și pontaj&quot;">​</a></h3><p>Perioada de raport și pontaj este stabilită de conducerea departamentului.</p><hr><h3 id="_2-5-invoiri" tabindex="-1">2.5 Învoiri <a class="header-anchor" href="#_2-5-invoiri" aria-label="Permalink to &quot;2.5 Învoiri&quot;">​</a></h3><p>În cazul imposibilității efectuării raportului, membrii trebuie să solicite învoire.</p><h3 id="reguli-10" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-10" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Cererile de învoire trebuie depuse prin canalele oficiale.</li><li>Învoirea trebuie aprobată înainte de expirarea perioadei de raport.</li></ul><hr><h3 id="_2-6-sedinte-si-activitati-obligatorii" tabindex="-1">2.6 Ședințe și activități obligatorii <a class="header-anchor" href="#_2-6-sedinte-si-activitati-obligatorii" aria-label="Permalink to &quot;2.6 Ședințe și activități obligatorii&quot;">​</a></h3><p>Participarea la activitățile obligatorii este necesară.</p><h3 id="reguli-11" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-11" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Absențele trebuie motivate.</li><li>Cererile de învoire trebuie aprobate înainte de activitate.</li></ul><hr><h3 id="_2-7-promovari" tabindex="-1">2.7 Promovări <a class="header-anchor" href="#_2-7-promovari" aria-label="Permalink to &quot;2.7 Promovări&quot;">​</a></h3><p>În perioada unei învoiri sau scutiri, dreptul la promovare poate fi suspendat.</p><hr><h3 id="_2-8-organizarea-departamentului" tabindex="-1">2.8 Organizarea departamentului <a class="header-anchor" href="#_2-8-organizarea-departamentului" aria-label="Permalink to &quot;2.8 Organizarea departamentului&quot;">​</a></h3><p>Repartizarea personalului se realizează conform gradului și deciziilor conducerii.</p><hr><h2 id="cap-3-promovari-si-avansari" tabindex="-1">CAP. 3 - PROMOVĂRI ȘI AVANSĂRI <a class="header-anchor" href="#cap-3-promovari-si-avansari" aria-label="Permalink to &quot;CAP. 3 - PROMOVĂRI ȘI AVANSĂRI&quot;">​</a></h2><h3 id="_3-1-promovari" tabindex="-1">3.1 Promovări <a class="header-anchor" href="#_3-1-promovari" aria-label="Permalink to &quot;3.1 Promovări&quot;">​</a></h3><p>Promovările sunt acordate pe baza performanței.</p><h3 id="criterii" tabindex="-1">Criterii <a class="header-anchor" href="#criterii" aria-label="Permalink to &quot;Criterii&quot;">​</a></h3><ul><li>Activitate.</li><li>Implicare.</li><li>Vechime.</li><li>Comportament.</li><li>Rezultate obținute.</li></ul><hr><h3 id="_3-2-sanctiuni-disciplinare" tabindex="-1">3.2 Sancțiuni disciplinare <a class="header-anchor" href="#_3-2-sanctiuni-disciplinare" aria-label="Permalink to &quot;3.2 Sancțiuni disciplinare&quot;">​</a></h3><p>Un membru sancționat poate pierde temporar dreptul la promovare.</p><hr><h3 id="_3-3-decizia-conducerii" tabindex="-1">3.3 Decizia conducerii <a class="header-anchor" href="#_3-3-decizia-conducerii" aria-label="Permalink to &quot;3.3 Decizia conducerii&quot;">​</a></h3><p>Conducerea poate acorda sau amâna promovările în funcție de necesitățile departamentului.</p><hr><h3 id="_3-4-certificate-obligatorii" tabindex="-1">3.4 Certificate obligatorii <a class="header-anchor" href="#_3-4-certificate-obligatorii" aria-label="Permalink to &quot;3.4 Certificate obligatorii&quot;">​</a></h3><p>Anumite grade necesită certificări și o perioadă minimă de activitate.</p><hr><h2 id="cap-4-statia-radio" tabindex="-1">CAP. 4 - STAȚIA RADIO <a class="header-anchor" href="#cap-4-statia-radio" aria-label="Permalink to &quot;CAP. 4 - STAȚIA RADIO&quot;">​</a></h2><h3 id="_4-1-utilizarea-statiei" tabindex="-1">4.1 Utilizarea stației <a class="header-anchor" href="#_4-1-utilizarea-statiei" aria-label="Permalink to &quot;4.1 Utilizarea stației&quot;">​</a></h3><p>Stația radio este obligatorie în timpul serviciului.</p><h3 id="reguli-12" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-12" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Toți polițiștii aflați în serviciu trebuie să fie conectați.</li><li>Frecvențele oficiale trebuie utilizate permanent.</li></ul><hr><h3 id="_4-2-accesul-la-frecvente" tabindex="-1">4.2 Accesul la frecvențe <a class="header-anchor" href="#_4-2-accesul-la-frecvente" aria-label="Permalink to &quot;4.2 Accesul la frecvențe&quot;">​</a></h3><h3 id="reguli-13" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-13" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Accesul la frecvențele Poliției este interzis în afara serviciului.</li><li>Accesul neautorizat poate fi sancționat.</li></ul><hr><h3 id="_4-3-comunicarea-radio" tabindex="-1">4.3 Comunicarea radio <a class="header-anchor" href="#_4-3-comunicarea-radio" aria-label="Permalink to &quot;4.3 Comunicarea radio&quot;">​</a></h3><p>Stația radio trebuie utilizată exclusiv pentru activitatea operativă.</p><h3 id="reguli-14" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-14" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Transmite doar informații relevante.</li><li>Evită conversațiile inutile.</li></ul><hr><h3 id="_4-4-canalele-radio" tabindex="-1">4.4 Canalele radio <a class="header-anchor" href="#_4-4-canalele-radio" aria-label="Permalink to &quot;4.4 Canalele radio&quot;">​</a></h3><p>Fiecare canal are o destinație specifică.</p><h3 id="reguli-15" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-15" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Respectă organizarea canalelor radio.</li><li>Utilizează canalul corespunzător activității desfășurate.</li></ul><hr><h3 id="_4-5-departamente-speciale" tabindex="-1">4.5 Departamente speciale <a class="header-anchor" href="#_4-5-departamente-speciale" aria-label="Permalink to &quot;4.5 Departamente speciale&quot;">​</a></h3><p>Accesarea canalelor speciale fără motiv este interzisă.</p><hr><h2 id="cap-5-dispecerat" tabindex="-1">CAP. 5 - DISPECERAT <a class="header-anchor" href="#cap-5-dispecerat" aria-label="Permalink to &quot;CAP. 5 - DISPECERAT&quot;">​</a></h2><h3 id="_5-1-rolul-dispeceratului" tabindex="-1">5.1 Rolul dispeceratului <a class="header-anchor" href="#_5-1-rolul-dispeceratului" aria-label="Permalink to &quot;5.1 Rolul dispeceratului&quot;">​</a></h3><p>Dispeceratul reprezintă principalul centru de coordonare al Poliției.</p><hr><h3 id="_5-2-comunicarea-prin-dispecerat" tabindex="-1">5.2 Comunicarea prin dispecerat <a class="header-anchor" href="#_5-2-comunicarea-prin-dispecerat" aria-label="Permalink to &quot;5.2 Comunicarea prin dispecerat&quot;">​</a></h3><h3 id="reguli-16" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-16" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Mesajele trebuie să fie clare.</li><li>Mesajele trebuie să fie concise.</li><li>Mesajele trebuie să fie relevante.</li></ul><hr><h3 id="_5-3-utilizare-necorespunzatoare" tabindex="-1">5.3 Utilizare necorespunzătoare <a class="header-anchor" href="#_5-3-utilizare-necorespunzatoare" aria-label="Permalink to &quot;5.3 Utilizare necorespunzătoare&quot;">​</a></h3><p>Este interzisă folosirea dispeceratului pentru:</p><ul><li>Glume.</li><li>Conversații fără relevanță.</li><li>Spam.</li></ul><hr><h3 id="_5-4-monitorizarea-informatiilor" tabindex="-1">5.4 Monitorizarea informațiilor <a class="header-anchor" href="#_5-4-monitorizarea-informatiilor" aria-label="Permalink to &quot;5.4 Monitorizarea informațiilor&quot;">​</a></h3><p>Toți membrii aflați în serviciu trebuie să urmărească permanent informațiile transmise.</p><hr><h3 id="_5-5-utilizare-roleplay" tabindex="-1">5.5 Utilizare Roleplay <a class="header-anchor" href="#_5-5-utilizare-roleplay" aria-label="Permalink to &quot;5.5 Utilizare Roleplay&quot;">​</a></h3><p>Dispeceratul poate fi utilizat doar în interes de serviciu.</p><hr><h2 id="cap-6-certificate-si-specializari" tabindex="-1">CAP. 6 - CERTIFICATE ȘI SPECIALIZĂRI <a class="header-anchor" href="#cap-6-certificate-si-specializari" aria-label="Permalink to &quot;CAP. 6 - CERTIFICATE ȘI SPECIALIZĂRI&quot;">​</a></h2><h3 id="_6-1-specializari" tabindex="-1">6.1 Specializări <a class="header-anchor" href="#_6-1-specializari" aria-label="Permalink to &quot;6.1 Specializări&quot;">​</a></h3><p>Poliția <strong>Legacy Of CLT</strong> pune la dispoziția membrilor certificări și specializări operaționale.</p><hr><h3 id="_6-2-acces-la-echipamente" tabindex="-1">6.2 Acces la echipamente <a class="header-anchor" href="#_6-2-acces-la-echipamente" aria-label="Permalink to &quot;6.2 Acces la echipamente&quot;">​</a></h3><p>Accesul la anumite echipamente și vehicule este condiționat de obținerea certificărilor.</p><hr><h3 id="_6-3-examene" tabindex="-1">6.3 Examene <a class="header-anchor" href="#_6-3-examene" aria-label="Permalink to &quot;6.3 Examene&quot;">​</a></h3><p>Examenele pentru certificări sunt organizate de instructorii autorizați.</p><hr><h3 id="_6-4-reexaminare" tabindex="-1">6.4 Reexaminare <a class="header-anchor" href="#_6-4-reexaminare" aria-label="Permalink to &quot;6.4 Reexaminare&quot;">​</a></h3><p>În cazul respingerii unui examen, acesta poate fi susținut din nou după perioada stabilită de regulament.</p><hr><h3 id="_6-5-instruirea-colegilor" tabindex="-1">6.5 Instruirea colegilor <a class="header-anchor" href="#_6-5-instruirea-colegilor" aria-label="Permalink to &quot;6.5 Instruirea colegilor&quot;">​</a></h3><p>Membrii certificați pot participa la pregătirea colegilor care doresc să obțină aceeași specializare.</p><hr><h2 id="cap-7-dispozitii-finale" tabindex="-1">CAP. 7 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-7-dispozitii-finale" aria-label="Permalink to &quot;CAP. 7 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_7-1-aplicarea-regulamentului" tabindex="-1">7.1 Aplicarea regulamentului <a class="header-anchor" href="#_7-1-aplicarea-regulamentului" aria-label="Permalink to &quot;7.1 Aplicarea regulamentului&quot;">​</a></h3><p>Toți membrii Poliției <strong>Legacy Of CLT</strong> au obligația de a respecta prezentul regulament.</p><h3 id="reguli-17" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-17" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Nerespectarea regulamentului poate atrage sancțiuni disciplinare.</li><li>Conducerea departamentului își rezervă dreptul de a interpreta și aplica regulamentul în funcție de situație.</li><li>Regulamentul poate fi modificat ori de câte ori este necesar.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Scopul prezentului regulament este menținerea unui departament profesionist, organizat și orientat către un <strong>Roleplay</strong> de calitate.</p><p>Respectarea tuturor prevederilor este obligatorie pentru fiecare membru al <strong>Poliției Legacy Of CLT</strong>.</p>',154)])])}const m=i(t,[["render",o]]);export{d as __pageData,m as default};
